$('#school-grid').innerHTML = schools.map((s,i)=>`<button class="school" data-school="${s.id}"><span class="school-top"><span class="school-icon">${s.icon}</span><span class="school-no">0${i+1} / DMDU</span></span><h3>${s.name}</h3><div class="school-en">${s.en}</div><p>${s.desc}</p><span class="school-bottom">${s.tags}<b>↗</b></span></button>`).join('');
const select = $('#college');
schools.forEach(s=>{const option=document.createElement('option');option.value=s.id;option.textContent=s.name;select.append(option);});
$('#news-list').innerHTML=stories.map((s,i)=>`<article class="news-item" data-category="${s.cat}"><button data-story="${s.id}"><span class="news-index">0${i+1}</span><span class="news-tag">${s.tag}</span><span><h3>${s.title}</h3><p>${s.desc}</p></span><span class="news-arrow">↗</span></button></article>`).join('');
function openDialog(dialog){dialog.showModal();document.body.style.overflow='hidden';}
function closeDialog(dialog){dialog.close();}
document.querySelectorAll('dialog').forEach(dialog=>{
 dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.style.overflow='';});
 dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(dialog);});
 dialog.querySelector('[data-close]').addEventListener('click',()=>closeDialog(dialog));
});
function enroll(id){if($('#detail-dialog').open)closeDialog($('#detail-dialog'));$('#enroll-input').hidden=false;$('#enroll-output').hidden=true;if(id)select.value=id;openDialog($('#enroll-dialog'));}
document.querySelectorAll('[data-enroll]').forEach(b=>b.addEventListener('click',()=>enroll()));
document.querySelectorAll('[data-school]').forEach(b=>b.addEventListener('click',()=>{const s=schools.find(s=>s.id===b.dataset.school);$('#detail-content').innerHTML=`<p class="eyebrow">${s.en}</p><h2>${s.icon} ${s.name}</h2><span class="detail-chip">脑洞专业 · 快乐学制 · 想学多久学多久</span><p>${s.desc}</p><h3>本学期快乐培养方案</h3><ul>${s.courses.map(c=>`<li>${c}</li>`).join('')}</ul><h3>想象中的就业方向</h3><p>${s.job}</p><h3>学院精神</h3><p>“${s.motto}”</p><button class="button green" id="apply-school">这个专业适合我 <span>↗</span></button><p class="fine">虚构学院与课程，仅供娱乐。</p>`;$('#apply-school').addEventListener('click',()=>enroll(s.id));openDialog($('#detail-dialog'));}));
document.querySelectorAll('[data-story]').forEach(b=>b.addEventListener('click',()=>{const s=stories.find(s=>s.id===Number(b.dataset.story));$('#detail-content').innerHTML=`<p class="eyebrow">THE VERY UNOFFICIAL TIMES / ${s.tag}</p><h2>${s.title}</h2>${s.body.split('\n\n').map(p=>`<p>${p}</p>`).join('')}<p class="fine">奶龙大学整活编辑部 · 虚构新闻，认真开心</p>`;openDialog($('#detail-dialog'));}));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('[data-category]').forEach(a=>a.hidden=b.dataset.filter!=='all'&&a.dataset.category!==b.dataset.filter);}));
$('#menu').addEventListener('click',()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));$('#menu').setAttribute('aria-label',open?'收起菜单':'展开菜单');});
$('#nav').addEventListener('click',e=>{if(e.target.closest('a,button')){$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');$('#menu').setAttribute('aria-label','展开菜单');}});
